// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import { auditDesigns } from "../../../scripts/design-audit.mjs";

const adr = (number, status, slug = "thing") => ({
  number,
  file: `${number}-${slug}.md`,
  path: `docs/adr/${number}-${slug}.md`,
  title: "A decision",
  status,
});

const row = (number, status, decided_by, slug = "thing") => ({
  id: `design:${number}-${slug}`,
  adr_path: `docs/adr/${number}-${slug}.md`,
  title: `ADR-${number}`,
  status,
  decided_by,
});

const kinds = (findings) => findings.map((f) => f.kind);

describe("auditDesigns", () => {
  it("reports nothing when every file has a matching decided row", () => {
    const findings = auditDesigns(
      [adr("0001", "Accepted"), adr("0002", "Proposed", "other")],
      [row("0001", "accepted", "monk-eee"), row("0002", "proposed", null, "other")]
    );
    expect(findings).toEqual([]);
  });

  it("flags an ADR that was never registered", () => {
    const findings = auditDesigns([adr("0048", "Proposed")], []);
    expect(kinds(findings)).toEqual(["unregistered"]);
    expect(findings[0].adr).toBe("0048");
  });

  it("flags a ledger row whose ADR is not present here", () => {
    const findings = auditDesigns([], [row("0036", "accepted", "monk-eee")]);
    expect(kinds(findings)).toEqual(["orphan"]);
  });

  it("flags a file and ledger that disagree about status", () => {
    const findings = auditDesigns([adr("0020", "Accepted")], [row("0020", "proposed", null)]);
    expect(kinds(findings)).toEqual(["disagreement"]);
    expect(findings[0].detail).toMatch(/file says Accepted, ledger says proposed/);
  });

  // The ADR-0047 shape: a reconciled import takes the status out of the file,
  // so a row can be `accepted` with nobody named as the decider. Accepting again
  // cannot repair it, because deciding twice is not an undo — ADR-0051 added
  // `attribute` for exactly this row, which records the decider and leaves the
  // status alone. The advice must say so: reopening would throw away an
  // acceptance that already holds and send the row back to proposed.
  it("flags a decision that names no decider, and points it at attribute", () => {
    const findings = auditDesigns([adr("0001", "Accepted")], [row("0001", "accepted", null)]);
    expect(kinds(findings)).toEqual(["undecided"]);
    expect(findings[0].detail).toMatch(/design_decide/);
    expect(findings[0].detail).toMatch(/attribute/);
    expect(findings[0].detail).not.toMatch(/\breopen\b/);
  });

  it("does not expect a decider on a proposed row", () => {
    const findings = auditDesigns([adr("0001", "Proposed")], [row("0001", "proposed", null)]);
    expect(findings).toEqual([]);
  });

  // Before ADR-0050 the ledger had no way to hold "Superseded by X", so this
  // was reported as an unrepresentable note. Now it can, and a file claiming
  // supersession the ledger was never told about is ordinary drift.
  it("flags a superseded file the ledger has not been told about", () => {
    const findings = auditDesigns(
      [adr("0018", "Superseded by [ADR-0032](0032-x.md)")],
      [row("0018", "accepted", "monk-eee")]
    );
    expect(kinds(findings)).toEqual(["supersession"]);
    expect(findings[0].detail).toMatch(/design_decide/);
    expect(findings[0].detail).toMatch(/supersede/);
  });

  it("reports nothing when both sides agree the design was superseded", () => {
    const recorded = {
      ...row("0018", "accepted", "monk-eee"),
      superseded: { by_design: "design:0032-x", at: 1, by: "monk-eee" },
    };
    const findings = auditDesigns([adr("0018", "Superseded by [ADR-0032](0032-x.md)")], [recorded]);
    expect(findings).toEqual([]);
  });

  // The reverse is drift too: a reader following the file would act on a
  // decision the ledger knows was withdrawn.
  it("flags a ledger supersession the file does not mention", () => {
    const recorded = {
      ...row("0018", "accepted", "monk-eee"),
      superseded: { by_design: "design:0032-x", at: 1, by: "monk-eee" },
    };
    const findings = auditDesigns([adr("0018", "Accepted")], [recorded]);
    expect(kinds(findings)).toEqual(["supersession"]);
    expect(findings[0].detail).toMatch(/the file does not say so/);
  });
});
